using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Staff of the Magi (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class StaffOfTheMagi2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("staff-of-the-magi", null, 0, MagicItemType.Staff, ItemRarity.Legendary, true, ContentSource.Srd51,
			Charges(50, ItemRecharge.LongRest, "4d6+2", Effect(MagicEffectKind.AttackAndDamage, 2), Effect(MagicEffectKind.SpellAttack, 2)),
			("Bastone dei magi", "Bastone, leggendario (richiede sintonia con un mago, uno stregone o un warlock)",
			"Questo bastone può essere impugnato come un bastone ferrato magico che garantisce un bonus di +2 ai tiri per colpire e ai tiri per i danni effettuati con esso. Mentre il personaggio lo impugna, ottiene un bonus di +2 ai tiri per colpire con incantesimo.\n\nIl bastone possiede 50 cariche per le proprietà descritte di seguito e recupera 4d6 + 2 cariche consumate all'alba di ogni giorno. Se il personaggio consuma l'ultima carica, deve tirare un d20; se ottiene 20, il bastone recupera 1d12 + 1 cariche.\n\n***Assorbimento degli incantesimi.*** Mentre il personaggio impugna il bastone, dispone di vantaggio ai tiri salvezza contro gli incantesimi. Può inoltre usare la sua reazione quando un'altra creatura lancia un incantesimo che ha solo lui come bersaglio. Se lo fa, il bastone assorbe la magia dell'incantesimo, annullandone gli effetti e ottenendo un numero di cariche pari al livello dell'incantesimo assorbito. Tuttavia, se così facendo il numero totale delle cariche del bastone supera 50, il bastone esplode come se il personaggio avesse attivato il suo colpo del castigo (vedi di seguito).\n\n***Incantesimi.*** Mentre il personaggio impugna il bastone, può usare un'azione per consumare alcune cariche e lanciare uno dei seguenti incantesimi usando la CD del tiro salvezza sull'incantesimo e la sua caratteristica da incantatore: *dissolvi magie* (3 cariche), *evoca elementale* (7 cariche), *fulmine* (versione di 7° livello, 7 cariche), *invisibilità* (2 cariche), *muro di fuoco* (4 cariche), *palla di fuoco* (versione di 7° livello, 7 cariche), *passapareti* (5 cariche), *ragnatela* (2 cariche), *scassinare* (2 cariche), *sfera infuocata* (2 cariche), *spostamento planare* (7 cariche), *telecinesi* (5 cariche) o *tempesta di ghiaccio* (4 cariche).\n\nIl personaggio può anche usare un'azione per lanciare con il bastone uno degli incantesimi seguenti senza spendere alcuna carica: *individuazione del magico, ingrandire/ridurre, luce, mano magica, protezione dal bene e dal male* o *serratura arcana.*\n\n***Colpo del castigo.*** Il personaggio può usare un'azione per spezzare il bastone sul ginocchio o contro una superficie solida ed effettuare un colpo del castigo. Il bastone è distrutto e sprigiona la magia che gli restava in un'esplosione che si espande fino a riempire una sfera del raggio di 9 metri centrata su di esso.\n\nIl personaggio ha una probabilità del 50% di spostarsi istantaneamente su un piano di esistenza casuale per evitare l'esplosione. Se non riesce a evitare l'effetto, subisce danni da forza pari a 16 × il numero di cariche rimanenti nel bastone. Ogni altra creatura nell'area deve effettuare un tiro salvezza su Destrezza con CD 17: se lo fallisce, subisce un ammontare di danni basato sulla sua distanza dal punto di origine dell'esplosione, come indicato nella tabella sottostante. Ogni creatura che supera il tiro salvezza subisce soltanto la metà di quei danni.\n\n| Distanza dall'origine | Danni |\n|---|---|\n| 3 m o meno | 8 × il numero di cariche nel bastone |\n| Più di 3 m, fino a 6 m | 6 × il numero di cariche nel bastone |\n| Più di 6 m, fino a 9 m | 4 × il numero di cariche nel bastone |", null),
			("Staff of the Magi", "Staff, legendary (requires attunement by a sorcerer, warlock, or wizard)",
			"This staff can be wielded as a magic quarterstaff that grants a +2 bonus to attack and damage rolls made with it. While you hold it, you gain a +2 bonus to spell attack rolls.\n\nThe staff has 50 charges for the following properties. It regains 4d6 + 2 expended charges daily at dawn. If you expend the last charge, roll a d20. On a 20, the staff regains 1d12 + 1 charges.\n\n***Spell Absorption.*** While holding the staff, you have advantage on saving throws against spells. In addition, you can use your reaction when another creature casts a spell that targets only you. If you do, the staff absorbs the magic of the spell, canceling its effect and gaining a number of charges equal to the absorbed spell's level. However, if doing so brings the staff's total number of charges above 50, the staff explodes as if you activated its retributive strike (see below).\n\n***Spells.*** While holding the staff, you can use an action to expend some of its charges to cast one of the following spells from it, using your spell save DC and spellcasting ability: conjure elemental (7 charges), dispel magic (3 charges), fireball (7th-level version, 7 charges), flaming sphere (2 charges), ice storm (4 charges), invisibility (2 charges), knock (2 charges), lightning bolt (7th-level version, 7 charges), passwall (5 charges), plane shift (7 charges), telekinesis (5 charges), wall of fire (4 charges), or web (2 charges).\n\nYou can also use an action to cast one of the following spells from the staff without using any charges: arcane lock, detect magic, enlarge/reduce, light, mage hand, or protection from evil and good.\n\n***Retributive Strike.*** You can use an action to break the staff over your knee or against a solid surface, performing a retributive strike. The staff is destroyed and releases its remaining magic in an explosion that expands to fill a 30-foot-radius sphere centered on it.\n\nYou have a 50 percent chance to instantly travel to a random plane of existence, avoiding the explosion. If you fail to avoid the effect, you take force damage equal to 16 × the number of charges in the staff. Every other creature in the area must make a DC 17 Dexterity saving throw. On a failed save, a creature takes an amount of damage based on how far away it is from the point of origin, as shown in the following table. On a successful save, a creature takes half as much damage.\n\n| Distance from Origin | Damage |\n|---|---|\n| 10 ft. away or closer | 8 × the number of charges in the staff |\n| 11 to 20 ft. away | 6 × the number of charges in the staff |\n| 21 to 30 ft. away | 4 × the number of charges in the staff |", null));
	}
}
